<?php
require_once "config/app.php";$page_title="Klasemen voting";$periode=periode_aktif($conn);$totals=[];foreach(['Kakang','Senduk'] as $cat){$s=$conn->prepare("SELECT k.*,COALESCE(SUM(v.jumlah_suara),0) total_suara FROM kontestan k LEFT JOIN voting v ON v.kontestan_id=k.id WHERE k.kategori=? GROUP BY k.id ORDER BY total_suara DESC,k.nomor_peserta");$s->bind_param("s",$cat);$s->execute();$totals[$cat]=$s->get_result()->fetch_all(MYSQLI_ASSOC);}
include "includes/header.php";?>
<div class="page-head"><div class="container"><div class="eyebrow">Hasil perolehan suara</div><h1 class="section-title">Klasemen voting</h1><p class="small-muted">Peringkat dihitung dari suara yang telah disetujui admin.</p></div></div><div class="container py-5"><?php foreach($totals as $cat=>$rows):$grand=array_sum(array_column($rows,'total_suara'));?><div class="mb-5"><div class="d-flex justify-content-between align-items-end mb-3"><div><span class="tag"><?=e($cat)?></span><h2 class="section-title mt-2 mb-0">Peringkat <?=e($cat)?></h2></div><div class="small-muted">Total suara sah: <strong><?=$grand?></strong></div></div><div class="panel p-3 p-md-4"><?php if(!$rows):?><p class="small-muted mb-0">Belum ada kontestan.</p><?php else:foreach($rows as $i=>$r):$pct=$grand?round($r['total_suara']/$grand*100,1):0;?><div class="d-flex gap-3 align-items-center mb-4"><div class="rank-number"><?=str_pad($i+1,2,'0',STR_PAD_LEFT)?></div><?php if($r['foto'] && file_exists(__DIR__.'/'.$r['foto'])):?><img src="<?=e($r['foto'])?>" class="avatar-sm"><?php else:?><div class="avatar-sm d-grid place-items-center" style="display:grid;place-items:center"><?=e(substr($r['nama'],0,1))?></div><?php endif;?><div class="flex-grow-1"><div class="d-flex justify-content-between gap-2"><strong><?=e($r['nama'])?></strong><strong><?=number_format($pct,1)?>%</strong></div><div class="small-muted"><?=e($r['nomor_peserta'])?> • <?=$r['total_suara']?> suara</div><div class="progress mt-2"><div class="progress-bar" style="width:<?=$pct?>%"></div></div></div></div><?php endforeach;endif;?></div></div><?php endforeach;?><p class="small-muted">Pembaruan data mengikuti pembayaran yang telah diverifikasi oleh admin.</p></div>
<?php include "includes/footer.php"; ?>